  struct { fd_ed25519_lane_point_t acc; fd_ed25519_lane_sel_t sel[2]; ulong const * src[1]; int neg[1]; } __attribute__((aligned(4096))) L;
  for( int i=0; i<5; i++ ) { L.acc.X.limb[i] = 0UL; L.acc.Y.limb[i] = (ulong)(i==0); L.acc.Z.limb[i] = (ulong)(i==0); L.acc.T.limb[i] = 0UL; }
