/* fd_ed25519_verify's checks on one signature, in its order and with its codes: S below the
   group order, A decodes, R decodes, A not of small order, R not of small order, then the
   group equation [S]B = R + [k]A as [k](-A) + [S]B == R */
int
fd_ed25519_serial_verify( uchar const msg[], /* msg_sz */
                           ulong msg_sz,
                           uchar const sig[ 64 ],
                           uchar const public_key[ 32 ],
                           fd_sha512_t * sha ) {
  uchar const * r = sig;
  uchar const * S = sig + 32;
  if( FD_UNLIKELY( !fd_curve25519_scalar_validate( S ) ) ) return FD_ED25519_ERR_SIG;
  fd_ed25519_lane_point_t A, R, Rc; int oka, okr;
  uchar const * ea[1] = { public_key }; uchar const * er[1] = { r };
  fd_ed25519_lane_decode_n( 2, &A, ea, &oka, &R, er, &okr );
  if( FD_UNLIKELY( !oka ) ) return FD_ED25519_ERR_PUBKEY;
  if( FD_UNLIKELY( !okr ) ) return FD_ED25519_ERR_SIG;
  if( FD_UNLIKELY( fd_ed25519_lane_small_order_mask( &A ) ) ) return FD_ED25519_ERR_PUBKEY;
  if( FD_UNLIKELY( fd_ed25519_lane_small_order_mask( &R ) ) ) return FD_ED25519_ERR_SIG;
  uchar k[ 64 ];
  fd_sha512_fini( fd_sha512_append( fd_sha512_append( fd_sha512_append( fd_sha512_init( sha ), r, 32UL ), public_key, 32UL ), msg, msg_sz ), k );
  fd_curve25519_scalar_reduce( k, k );
  fd_ed25519_lane_neg( &A.X, &A.X ); fd_ed25519_lane_neg( &A.T, &A.T );  /* -A */
  fd_ed25519_serial_double_scalar_mul( &Rc, k, &A, S );
  return FD_LIKELY( fd_ed25519_lane_eq_z1_mask( &Rc, &R ) ) ? FD_ED25519_SUCCESS : FD_ED25519_ERR_MSG;
}
